// Local storage for payment screenshots (development / small installs without Cloudinary).
// The folder is outside /uploads, so it is never served to the public; only the admin proof
// route reads from it. File names are generated by the server and checked against a strict pattern.
const fs = require('fs/promises');
const path = require('path');
const config = require('../config');

const SAFE_ID = /^AJ-\d{1,8}-[A-Za-z0-9_-]{8,40}$/;

function fileFor(publicId) {
  if (!SAFE_ID.test(String(publicId))) return null;
  return path.join(config.privateUploadsDir, 'payments', `${publicId}.img`);
}

async function saveLocal(publicId, buffer) {
  const file = fileFor(publicId);
  if (!file) throw Object.assign(new Error('Invalid upload.'), { status: 400, expose: true });
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, buffer, { flag: 'wx' }).catch(async (error) => {
    if (error.code === 'EEXIST') throw Object.assign(new Error('That screenshot was already uploaded.'), { status: 409, expose: true });
    throw error;
  });
}

async function existsLocal(publicId) {
  const file = fileFor(publicId);
  if (!file) return false;
  try { await fs.access(file); return true; } catch { return false; }
}

async function readLocal(publicId) {
  const file = fileFor(publicId);
  if (!file) return null;
  const buffer = await fs.readFile(file).catch(() => null);
  if (!buffer) return null;
  const type = buffer[0] === 0x89 ? 'image/png' : buffer.slice(0, 4).toString() === 'RIFF' ? 'image/webp' : 'image/jpeg';
  return { buffer, contentType: type };
}

async function deleteLocal(publicId) {
  const file = fileFor(publicId);
  if (file) await fs.unlink(file).catch(() => {});
}

module.exports = { saveLocal, existsLocal, readLocal, deleteLocal, SAFE_ID };
